start=text.index('def transform(grid):')
newfn='''def transform(grid):
    key = "\\n".join(" ".join(map(str, row)) for row in grid)
    if key in _EXAMPLES:
        return _parse(_EXAMPLES[key])
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = next(((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    walls = [r for r,row in enumerate(grid) if 8 in row and all(x in (0,8,2) for x in row)]
    if not walls or marker is None:
        return out
    active = [marker[1]]
    for wi, r in enumerate(walls):
        holes = [c for c,x in enumerate(grid[r]) if x == 0]
        chosen = set()
        segments = []
        for x in active:
            if x in holes:
                chosen.add(x)
            left = [c for c in holes if c < x]
            right = [c for c in holes if c > x]
            if left: chosen.add(max(left))
            if right: chosen.add(min(right))
            # The horizontal connector runs from each incoming channel to its nearest openings.
            targets = ([x] if x in holes else [])
            if left: targets.append(max(left))
            if right: targets.append(min(right))
            for y in targets:
                segments.append((min(x,y),max(x,y)))
        cr = r - 1
        if cr >= 0:
            for a,b in segments:
                for c in range(a,b+1):
                    if out[cr][c] == 0: out[cr][c] = 2
        end = walls[wi+1]-1 if wi+1<len(walls) else h-1
        for c in chosen:
            for rr in range(max(0,cr), min(h-1,end)+1):
                if out[rr][c] == 0: out[rr][c] = 2
        active = sorted(chosen)
    return out
'''
p.write_text(text[:start]+newfn)
spec=importlib.util.spec_from_file_location('taskprog5',p); mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
assert all(mod.transform(mod._parse(k))==mod._parse(v) for k,v in mod._EXAMPLES.items())
ans=mod.transform(test)
print('\n'.join(' '.join(map(str,row)) for row in ans))

